{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or REPLACE TABLE SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS AS Select * from ( With final as (Select * from ( Select * from ( With overall as ( Select CASE WHEN POSITION(\'-\' IN \"ITEM CODE\") > 0 AND LEFT(\"ITEM CODE\", 2) = \'SH\' THEN SPLIT_PART(\"ITEM CODE\", \'-\', 1) WHEN POSITION(\'-\' IN \"ITEM CODE\") > 0 THEN SPLIT_PART(\"ITEM CODE\", \'-\', 1) || \'-\' || SPLIT_PART(\"ITEM CODE\", \'-\', 2) ELSE \"ITEM CODE\" END AS sku_group, \"ITEM CODE\", branch_code_priority , \"BRANCH NAME\", TO_DATE( \"RECEIPT DATE\", \'DD/MM/YYYY\' ) AS Inward_date, SUM(\"PUR QTY\") AS qty, \'PUV Verification Pending\' as Status, DATEDIFF( DAY, TO_DATE(\"RECEIPT DATE\", \'DD/MM/YYYY\'), CURRENT_DATE ) AS aging from ( SELECT a.*, b.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification a left join ( SELECT DISTINCT e.\"BRANCH NAME\", s.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification e LEFT JOIN snitch_db.maplemonk.storepriority s ON e.\"BRANCH NAME\" LIKE \'%\' || s.branch_name_priority || \'%\') b on a.\"BRANCH NAME\" =b.\"BRANCH NAME\" where \"GOODS IN TRANSIT\" = \'True\') GROUP BY 1,2,3,4,5 Union ALL SELECT CASE WHEN POSITION(\'-\' IN \"EXPORT ADDITIONAL ITEM CODE\") > 0 AND LEFT(\"EXPORT ADDITIONAL ITEM CODE\", 2) = \'SH\' THEN SPLIT_PART(\"EXPORT ADDITIONAL ITEM CODE\", \'-\', 1) WHEN POSITION(\'-\' IN \"EXPORT ADDITIONAL ITEM CODE\") > 0 THEN SPLIT_PART(\"EXPORT ADDITIONAL ITEM CODE\", \'-\', 1) || \'-\' || SPLIT_PART(\"EXPORT ADDITIONAL ITEM CODE\", \'-\', 2) ELSE \"EXPORT ADDITIONAL ITEM CODE\" END AS sku_group, \"EXPORT ADDITIONAL ITEM CODE\", branch_code_priority, \"EXPORT PARTY NAME\", CASE WHEN \"EXPORT DOC DATE\" LIKE \'%/%/%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD/MM/YYYY\') WHEN \"EXPORT DOC DATE\" LIKE \'%-%-%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD-MM-YYYY\') ELSE NULL END AS Inward_date, SUM(\"EXPORT QUANTITY\") AS QTY_JIT, \'IN TRANSIT\' AS STATUS, DATEDIFF( DAY, CASE WHEN \"EXPORT DOC DATE\" LIKE \'%/%/%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD/MM/YYYY\') WHEN \"EXPORT DOC DATE\" LIKE \'%-%-%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD-MM-YYYY\') ELSE NULL END, CURRENT_DATE ) AS aging FROM ( SELECT a.*, b.branch_code_priority FROM snitch_db.maplemonk.offline_jit a LEFT JOIN ( SELECT DISTINCT e.\"EXPORT PARTY NAME\" AS \"EXPORT PARTY NAME\", s.branch_code_priority FROM snitch_db.maplemonk.offline_jit e LEFT JOIN snitch_db.maplemonk.storepriority s ON REGEXP_REPLACE(e.\"EXPORT PARTY NAME\", \'-[^-]*$\', \'\') LIKE \'%\' || s.branch_name_priority || \'%\' ) b ON a.\"EXPORT PARTY NAME\" = b.\"EXPORT PARTY NAME\" WHERE \"IMPORT QUANTITY\" = \'\' OR \"IMPORT QUANTITY\" IS NULL ) subquery GROUP BY sku_group, \"EXPORT ADDITIONAL ITEM CODE\", branch_code_priority, \"EXPORT PARTY NAME\", Inward_date UNION ALL Select SKU_GROUP, SKU, BRANCH_CODE, store, ORDER_DATE, sum(qty) AS qty, status, datediff(day,order_date,current_date) as Aging From ( With over as ( Select SKU_GROUP, SKU, BRANCH_CODE, STATE_, ORDER_DATE, sum(JIT) AS qty, status, datediff(day,order_date,current_date) as Aging from ( Select * FROM ( SELECT jit.*, sd.branch_code, sd.STATE_, sd.type, sd.status, sd.Dispatch_date, sd.order_received_date, DATEDIFF(\'DAY\', sd.Dispatch_date, COALESCE(sd.order_received_date, CURRENT_DATE())) as Days_JIT FROM ( SELECT order_name, order_date, sku_group, SKU, SUM(stock_qty) AS JIT, COALESCE(SUM(CASE WHEN size_mapped = \'XS\' THEN stock_qty ELSE 0 END), 0) AS XS_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'S\' THEN stock_qty ELSE 0 END), 0) AS S_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'M\' THEN stock_qty ELSE 0 END), 0) AS M_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'L\' THEN stock_qty ELSE 0 END), 0) AS L_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'XL\' THEN stock_qty ELSE 0 END), 0) AS XL_units_store, COALESCE(SUM(CASE WHEN size_mapped IN (\'XXL\', \'XXl\', \'2XL\') THEN stock_qty ELSE 0 END), 0) AS XXL_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'3XL\' THEN stock_qty ELSE 0 END), 0) AS XL3_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'4XL\' THEN stock_qty ELSE 0 END), 0) AS XL4_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'5XL\' THEN stock_qty ELSE 0 END), 0) AS XL5_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'6XL\' THEN stock_qty ELSE 0 END), 0) AS XL6_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'NA\' THEN stock_qty ELSE 0 END), 0) AS NA_units_store, (CASE WHEN XS_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_units_store > 0 THEN 1 ELSE 0 END)+ (CASE WHEN NA_units_store > 0 THEN 1 ELSE 0 END) AS num_size_available_REPLEN FROM ( SELECT order_name, order_date, CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END as sku_group, SKU, REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1)) AS size, count (distinct SALEORDERITEMCODE)AS stock_qty, CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END AS size_mapped FROM snitch_db.maplemonk.unicommerce_fact_items_snitch WHERE marketplace_mapped IN (\'OWN_STORE\', \'FRANCHISE_STORE\') AND order_name IN ( SELECT DISTINCT so_number FROM snitch_db.maplemonk.INWARD_DATA WHERE STATUS not IN(\'Cancelled\',\'DUPLICATE\',\'Dispatched to Store\',\'Returned\',\'RTS-LOGIC\',\'UNFILFILLABLE\') ) GROUP BY order_name, sku_group, SKU, order_date order by stock_qty desc ) subquery GROUP BY order_name, SKU,sku_group, order_date HAVING SUM(stock_qty) > 0 ) jit LEFT JOIN ( Select Distinct so_number , BRANCH_CODE,STATE_, type, status, TO_DATE(REPLACE(ORDER_DISPATCHED_DATE,\'-\', \'/\'), \'DD/MM/YYYY\') as Dispatch_date, TO_DATE(REPLACE(order_received_date,\'-\', \'/\'), \'DD/MM/YYYY\') as order_received_date from snitch_db.maplemonk.INWARD_DATA WHERE STATUS not IN(\'Cancelled\',\'DUPLICATE\',\'Dispatched to Store\',\'Returned\',\'RTS-LOGIC\',\'UNFILFILLABLE\') ) sd ON jit.order_name = sd.so_number ) ) group by 1,2,3,4,5,7), dets as ( Select * from snitch_db.maplemonk.storepriority ) Select a.*, b.BRANCH_NAME_PRIORITY, coalesce(b.BRANCH_NAME_PRIORITY,a.state_) as Store from over a left join dets b on a.branch_code =b.BRANCH_CODE_PRIORITY ) group by 1,2,3,5,4,7 ) , deatilas as ( select * from ( select CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END as sku_group, product_name, category, final_ros, natural_ros, sku_class , ROW_NUMBER() OVER (PARTITION BY CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END ORDER BY 1) AS rn, from snitch_db.maplemonk.availability_master_v2) where rn=1 ) SELECT a.*, b.product_name, b.category, b.final_ros AS online_final_ros, b.natural_ros AS online_natural_ros, b.sku_class FROM overall a LEFT JOIN deatilas b ON a.SKU_GROUP = b.sku_group ) where sku_group not like \'%CB%\' ) ), haa as ( Select * from ( SELECT DISTINCT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY order_date DESC) AS rn FROM snitch_db.maplemonk.STORE_fact_items_offline) WHERE rn = 1 ) Select a.SKU_GROUP, a.\"ITEM CODE\", a.INWARD_DATE, a.QTY, a.STATUS, a.AGING, a.PRODUCT_NAME, a.CATEGORY, a.ONLINE_FINAL_ROS, a.ONLINE_NATURAL_ROS, a.SKU_CLASS, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN 28 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN 40 WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN 42 ELSE COALESCE(b.branch_code, a.branch_code_priority) END AS branch_code, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN \'SNITCH - COCO - METRO MALL\' ELSE COALESCE(b.marketplace_mapped, a.\"BRANCH NAME\") END AS Store from final a left join haa b on a.branch_code_priority = b.branch_code ) ; CREATE OR REPLACE TABLE snitch_db.maplemonk.Offline_metrics_warehouse_stock AS SELECT a.*, b.PRODUCT_TYPE, b.OCCASSION_NEW AS OCCASSION, b.DESIGNS AS PRINT_DESIGN, b.COLLAR_NEW AS COLLAR, b.MATERIAL_NEW AS MATERIAL, b.SLEEVE_TYPE, b.FIT, b.STYLE, b.COLOR, b.CLOSURE, b.LENGTH, c.image_link FROM snitch_db.maplemonk.availability_master_v2 a LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) AS rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ) b ON a.sku_group = b.sku_group LEFT JOIN ( SELECT * FROM ( WITH product_images AS ( SELECT DISTINCT id, REPLACE(A.value:src, \'\"\', \'\') AS src, REPLACE(A.value:position, \'\"\', \'\') AS pst FROM snitch_db.maplemonk.shopifyindia_new_products, LATERAL FLATTEN(INPUT => IMAGES) A WHERE REPLACE(A.value:position, \'\"\', \'\') = \'1\' ) SELECT b.sku_group, a.src AS image_link, ROW_NUMBER() OVER (PARTITION BY b.sku_group ORDER BY b.sku_group) AS rn FROM product_images a LEFT JOIN snitch_db.maplemonk.availability_master_v2 b ON a.id = b.id ) WHERE rn = 1 ) c ON a.sku_group = c.sku_group; Create or replace table snitch_db.maplemonk.Offline_metrics as SELECT A.*, B.AM, B.RM, B.NSM, B.CITY, B.STATE, B.REGION, B.partner FROM snitch_db.maplemonk.Offline_Detailed_Summary AS A LEFT JOIN snitch_db.maplemonk.master_offine AS B ON A.BRANCH_CODE = B.\"BRANCH CODE\" WHERE A.marketplace_mapped NOT LIKE \'%WH%\' ; Create Or REPLACE Table snitch_db.maplemonk.Offline_Inventory_aging as WITH InventoryAging AS ( SELECT branch_code, BRANCH_NAME, REVERSE(SUBSTRING(REVERSE(LOGICUSERCODE), CHARINDEX(\'-\', REVERSE(LOGICUSERCODE)) + 1)) AS sku_group, SUM(stock_qty) AS total_inventory, DATEDIFF(DAY, TO_DATE(lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE) AS Age FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE DATE = CURRENT_DATE AND LOGICUSERCODE NOT LIKE (\'CB%\') GROUP BY branch_code, REVERSE(SUBSTRING(REVERSE(LOGICUSERCODE), CHARINDEX(\'-\', REVERSE(LOGICUSERCODE)) + 1)), TO_DATE(lot_pur_date, \'DD/MM/YYYY\'), BRANCH_NAME ), WeightedAging AS ( SELECT branch_code, BRANCH_NAME, sku_group, SUM(total_inventory * Age) AS total_weighted_age, SUM(total_inventory) AS total_inventory FROM InventoryAging GROUP BY branch_code, sku_group,BRANCH_NAME ), age as ( SELECT branch_code, BRANCH_NAME, sku_group, total_inventory, CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) AS final_weighted_age, CASE WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 30 THEN \'0-30\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 60 THEN \'31-60\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 90 THEN \'61-90\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 180 THEN \'91-180\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 360 THEN \'181-360\' ELSE \'>360\' END AS aging_interval FROM WeightedAging ORDER BY branch_code, sku_group,BRANCH_NAME ), meta as (Select * from (SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) AS rn FROM snitch_db.maplemonk.metafields_data)where rn=1) select a.*, b.product_type from age a left join meta b on a.sku_group=b.sku_group; Create or REPLACE table snitch_db.maplemonk.offline_master as Select a.*, B.AM, B.RM, B.NSM, B.CITY, B.STATE, B.REGION, B.partner From ( With details_23 as ( Select * from ( With offline_master as ( Select * from ( With master_final as ( Select * From ( With complete as ( Select * from ( With overall_jit as ( WITH Overall_fresh as ( SELECT * FROM ( wITH OVERALL AS (Select * FROM ( sELECT * FROM ( With OFFLINE AS ( Select * from ( WITH Master AS ( SELECT * FROM ( WITH sku_group_data AS ( SELECT sku_group, branch_code, order_date, suborder_quantity, return_quantity FROM ( WITH ABS AS ( SELECT sku_group, branch_code, order_date, suborder_quantity FROM snitch_db.MAPLEMONK.STORE_fact_items_offline ), ACC AS ( SELECT sku_group, branch_code, order_date, suborder_quantity AS return_quantity FROM snitch_db.MAPLEMONK.store_returns_fact_items ) SELECT A.*, IFNULL(B.return_quantity, 0) AS return_quantity FROM ABS A FULL OUTER JOIN ACC B ON A.sku_group = B.sku_group AND A.order_date = B.order_date AND A.branch_code = B.branch_code ) WHERE SKU_GROUP NOT LIKE \'CB%\' ), first_order_dates AS ( SELECT sku_group, branch_code, MIN(order_date) AS first_order_date, DATEDIFF(\'DAY\', MIN(order_date), CURRENT_DATE) AS days_since_first_order, DATEDIFF(\'DAY\', MIN(order_date), MAX(order_date)) AS total_days_sold FROM sku_group_data GROUP BY sku_group, branch_code ), total_sales AS ( SELECT sku_group_data.sku_group, sku_group_data.branch_code, first_order_dates.first_order_date, first_order_dates.days_since_first_order, first_order_dates.total_days_sold, SUM(return_quantity) AS total_returns, SUM(suborder_quantity) AS total_sales, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 30, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_30_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 15, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_15_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 7, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_7_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 90, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_90_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 60, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_60_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 180, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_180_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 30 THEN suborder_quantity ELSE 0 END) AS sales_last_30_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 15 THEN suborder_quantity ELSE 0 END) AS sales_last_15_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 7 THEN suborder_quantity ELSE 0 END) AS sales_last_7_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 60 THEN suborder_quantity ELSE 0 END) AS sales_last_60_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 90 THEN suborder_quantity ELSE 0 END) AS sales_last_90_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 180 THEN suborder_quantity ELSE 0 END) AS sales_last_180_days, CASE WHEN first_order_dates.total_days_sold = 0 THEN SUM(suborder_quantity) ELSE SUM(suborder_quantity) / first_order_dates.total_days_sold END AS natural_ros FROM sku_group_data INNER JOIN first_order_dates ON sku_group_data.sku_group = first_order_dates.sku_group AND sku_group_data.branch_code = first_order_dates.branch_code GROUP BY sku_group_data.sku_group, sku_group_data.branch_code, first_order_dates.first_order_date, first_order_dates.days_since_first_order, first_order_dates.total_days_sold ), enhanced_total_sales AS ( SELECT total_sales.*, GREATEST( total_sales.sales_first_30_days / 30, total_sales.sales_last_30_days / 30, total_sales.natural_ros ) AS max_first_30_last_30_natural_ros, GREATEST( total_sales.sales_first_30_days / 30, total_sales.sales_last_30_days / 30, total_sales.natural_ros, total_sales.sales_first_7_days / 7 ) AS max_first_30_last_30_natural_ros_first_7_days, CASE WHEN total_sales.total_sales = 0 THEN 0 ELSE (total_sales.total_returns / total_sales.total_sales) * 100 END AS average_return_since_first_order, CASE WHEN max_first_30_last_30_natural_ros > 10 THEN max_first_30_last_30_natural_ros WHEN max_first_30_last_30_natural_ros < 10 AND max_first_30_last_30_natural_ros_first_7_days > 20 THEN max_first_30_last_30_natural_ros_first_7_days WHEN total_sales.total_sales > 800 THEN GREATEST(natural_ros, sales_last_7_days / 7) ELSE natural_ros END AS final_ros FROM total_sales ) SELECT * FROM enhanced_total_sales ORDER BY total_sales DESC ) ), inventory AS ( SELECT REVERSE(SUBSTRING(REVERSE(LOGICUSERCODE), CHARINDEX(\'-\', REVERSE(LOGICUSERCODE)) + 1)) AS sku_group, BRANCH_CODE, SUM(STOCK_QTY) AS inventory, DATE, COALESCE(SUM(CASE WHEN PACK_NAME = \'XS\' OR PACK_NAME = \'28\' THEN STOCK_QTY ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'S\' OR PACK_NAME = \'30\' THEN STOCK_QTY ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'M\' OR PACK_NAME = \'32\' THEN STOCK_QTY ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'L\' OR PACK_NAME = \'34\' THEN STOCK_QTY ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'XL\' OR PACK_NAME = \'36\' THEN STOCK_QTY ELSE 0 END), 0) AS XL_units, COALESCE(SUM(CASE WHEN PACK_NAME IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN STOCK_QTY ELSE 0 END), 0) AS XXL_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'3XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL3_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'4XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL4_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'5XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL5_units, COALESCE(SUM(CASE WHEN PACK_NAME = \'6XL\' THEN STOCK_QTY ELSE 0 END), 0) AS XL6_units, (CASE WHEN XS_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_units > 0 THEN 1 ELSE 0 END) AS num_size_available FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE sku_group NOT LIKE \'CB%\' AND DATE = CURRENT_DATE GROUP BY sku_group, branch_code, DATE ) SELECT COALESCE(q.sku_group, b.sku_group) as SKU_GROUP_Final, COALESCE(q.branch_code, b.branch_code) as Store, COALESCE(q.TOTAL_RETURNS, 0) AS TOTAL_RETURNS, COALESCE(q.FIRST_ORDER_DATE, null) AS FIRST_ORDER_DATE, COALESCE(q.DAYS_SINCE_FIRST_ORDER, 0) AS DAYS_SINCE_FIRST_ORDER, COALESCE(q.TOTAL_SALES, 0) AS TOTAL_SALES, COALESCE(q.NATURAL_ROS, 0) AS NATURAL_ROS, COALESCE(q.AVERAGE_RETURN_SINCE_FIRST_ORDER, 0) AS AVERAGE_RETURN_SINCE_FIRST_ORDER, COALESCE(q.FINAL_ROS, 0) AS FINAL_ROS, COALESCE(q.SALES_FIRST_7_DAYS, 0) AS SALES_FIRST_7_DAYS, COALESCE(q.SALES_FIRST_15_DAYS, 0) AS SALES_FIRST_15_DAYS, COALESCE(q.SALES_FIRST_30_DAYS, 0) AS SALES_FIRST_30_DAYS, COALESCE(q.SALES_LAST_7_DAYS, 0) AS SALES_LAST_7_DAYS, COALESCE(q.SALES_LAST_15_DAYS, 0) AS SALES_LAST_15_DAYS, COALESCE(q.SALES_LAST_30_DAYS, 0) AS SALES_LAST_30_DAYS, COALESCE(b.INVENTORY, 0) AS INVENTORY, COALESCE(b.XS_UNITS, 0) as XS_UNITS, COALESCE(b.S_UNITS, 0) as S_UNITS, COALESCE(b.M_UNITS, 0) as M_UNITS, COALESCE(b.L_UNITS, 0) as L_UNITS, COALESCE(b.XL_UNITS, 0) as XL_UNITS, COALESCE(b.XXL_UNITS, 0) as XXL_UNITS, COALESCE(b.XL3_UNITS, 0) as XL3_UNITS, COALESCE(b.XL4_UNITS, 0) as XL4_UNITS, COALESCE(b.XL5_UNITS, 0) as XL5_UNITS, COALESCE(b.XL6_UNITS, 0) as XL6_UNITS, COALESCE(b.NUM_SIZE_AVAILABLE, 0) as NUM_SIZE_AVAILABLE FROM Master q FULL OUTER JOIN Inventory b ON q.sku_group = b.sku_group AND q.branch_code = b.branch_code ) ), availability_master_v2 as ( Select * from ( Select sku_group, price, product_name, category, final_ros, natural_ros, sku_class, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1) AS rn from snitch_db.maplemonk.availability_master_v2) where rn = 1 ) Select a.* , b.price, b.product_name, b.category, b.final_ros as online_final_ros, b.natural_ros as online_natural_ros, b.sku_class from OFFLINE a left join availability_master_v2 b on a. SKU_GROUP_Final = b.sku_group ) WHERE SKU_GROUP_Final NOT LIKE \'CB%\' ) ), details as ( Select * from ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY order_date DESC) AS row_number FROM snitch_db.maplemonk.STORE_fact_items_offline) where row_number =1 ) Select a.*, b.marketplace_mapped, from overall a left join details b on a.Store = b.branch_code ) ), Fresh as ( SELECT sku_group, branch_code, SUM(Fresh) AS Fresh FROM ( SELECT date, REVERSE(SUBSTRING(REVERSE(LOGICUSERCODE), CHARINDEX(\'-\', REVERSE(LOGICUSERCODE)) + 1)) AS sku_group, branch_code, branch_name, TO_DATE(lot_pur_date, \'DD/MM/YYYY\') AS lot_pur_date_formatted, SUM(stock_qty) AS Fresh FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE DATE = CURRENT_DATE AND LOGICUSERCODE NOT LIKE (\'CB%\') AND lot_pur_date_formatted >= CURRENT_DATE - 30 AND (branch_code, LOGICUSERCODE) NOT IN ( SELECT branch_code, sku FROM snitch_db.maplemonk.store_fact_items_offline GROUP BY branch_code, sku HAVING MIN(order_date) <= CURRENT_DATE - 30 ) GROUP BY date, sku_group, branch_code, branch_name, lot_pur_date_formatted ) grouped_data GROUP BY sku_group, branch_code ) Select a.*, coalesce(b.Fresh,0) as fresh_inventory from overall_fresh a left join fresh b on a.store = b.branch_code and a.sku_group_final =b.sku_group ), jit as ( SELECT BRANCH_CODE, STORE, SKU_GROUP, COALESCE(SUM(CASE WHEN extracted_value = \'XS\' OR extracted_value = \'28\' THEN Qty ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN extracted_value = \'S\' OR extracted_value = \'30\' THEN Qty ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN extracted_value = \'M\' OR extracted_value = \'32\' THEN Qty ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN extracted_value = \'L\' OR extracted_value = \'34\' THEN Qty ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN extracted_value = \'XL\' OR extracted_value = \'36\' THEN Qty ELSE 0 END), 0) AS XL_units, COALESCE(SUM(CASE WHEN extracted_value IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN Qty ELSE 0 END), 0) AS XXL_units, COALESCE(SUM(CASE WHEN extracted_value IN(\'3XL\',\'XXXL\') THEN Qty ELSE 0 END), 0) AS XL3_units, COALESCE(SUM(CASE WHEN extracted_value = \'4XL\' THEN Qty ELSE 0 END), 0) AS XL4_units, COALESCE(SUM(CASE WHEN extracted_value = \'5XL\' THEN Qty ELSE 0 END), 0) AS XL5_units, COALESCE(SUM(CASE WHEN extracted_value = \'6XL\' THEN Qty ELSE 0 END), 0) AS XL6_units, COALESCE(SUM(QTY),0) AS JIT_QTY FROM ( SELECT *, REVERSE(SUBSTRING(REVERSE(\"ITEM CODE\"), 1, CHARINDEX(\'-\', REVERSE(\"ITEM CODE\")) - 1)) AS extracted_value FROM snitch_db.maplemonk.JIT_OFFLINE_GOODS) GROUP BY BRANCH_CODE, SKU_GROUP,STORE ) SELECT COALESCE(a.SKU_GROUP_FINAL, B.SKU_GROUP) AS SKU_GROUP, COALESCE(A.STORE, B.BRANCH_CODE) AS BRANCH_CODE, COALESCE(A.MARKETPLACE_MAPPED, B.STORE) AS MARKETPLACE_MAPPED, A.FIRST_ORDER_DATE, COALESCE(A.TOTAL_SALES, 0) AS TOTAL_SALES, COALESCE(A.TOTAL_RETURNS, 0) AS TOTAL_RETURNS, COALESCE(A.DAYS_SINCE_FIRST_ORDER, 0) AS DAYS_SINCE_FIRST_ORDER, COALESCE(A.AVERAGE_RETURN_SINCE_FIRST_ORDER, 0) AS AVERAGE_RETURN_SINCE_FIRST_ORDER, COALESCE(A.NATURAL_ROS, 0) AS NATURAL_ROS, COALESCE(A.FINAL_ROS, 0) AS FINAL_ROS, COALESCE(A.SALES_FIRST_7_DAYS, 0) AS SALES_FIRST_7_DAYS, COALESCE(A.SALES_FIRST_15_DAYS, 0) AS SALES_FIRST_15_DAYS, COALESCE(A.SALES_FIRST_30_DAYS, 0) AS SALES_FIRST_30_DAYS, COALESCE(A.SALES_LAST_7_DAYS, 0) AS SALES_LAST_7_DAYS, COALESCE(A.SALES_LAST_15_DAYS, 0) AS SALES_LAST_15_DAYS, COALESCE(A.SALES_LAST_30_DAYS, 0) AS SALES_LAST_30_DAYS, COALESCE(A.INVENTORY, 0) AS INVENTORY, COALESCE(A.XS_UNITS, 0) AS XS_UNITS, COALESCE(A.S_UNITS, 0) AS S_UNITS, COALESCE(A.M_UNITS, 0) AS M_UNITS, COALESCE(A.L_UNITS, 0) AS L_UNITS, COALESCE(A.XL_UNITS, 0) AS XL_UNITS, COALESCE(A.XXL_UNITS, 0) AS XXL_UNITS, COALESCE(A.XL3_UNITS, 0) AS XL3_UNITS, COALESCE(A.XL4_UNITS, 0) AS XL4_UNITS, COALESCE(A.XL5_UNITS, 0) AS XL5_UNITS, COALESCE(A.XL6_UNITS, 0) AS XL6_UNITS, COALESCE(A.NUM_SIZE_AVAILABLE, 0) AS NUM_SIZE_AVAILABLE, COALESCE(A.FRESH_INVENTORY, 0) AS FRESH_INVENTORY, COALESCE(b.XS_UNITS, 0) AS jit_XS_units, COALESCE(b.S_UNITS, 0) AS jit_S_units, COALESCE(b.M_UNITS, 0) AS jit_M_units, COALESCE(b.L_UNITS, 0) AS jit_L_units, COALESCE(b.XL_UNITS, 0) AS jit_XL_units, COALESCE(b.XXL_UNITS, 0) AS jit_2XL_units, COALESCE(b.XL3_UNITS, 0) AS jit_3XL_units, COALESCE(b.XL4_UNITS, 0) AS jit_4XL_units, COALESCE(b.XL5_UNITS, 0) AS jit_5XL_units, COALESCE(b.XL6_UNITS, 0) AS jit_6XL_units, COALESCE(B.JIT_QTY, 0) AS JIT_QTY, CASE WHEN (COALESCE(A.S_UNITS, 0) + COALESCE(b.S_UNITS, 0) = 0 AND COALESCE(A.M_UNITS, 0) + COALESCE(b.M_UNITS, 0) = 0) OR (COALESCE(A.S_UNITS, 0) + COALESCE(b.S_UNITS, 0) = 0 AND COALESCE(A.L_UNITS, 0) + COALESCE(b.L_UNITS, 0) = 0) OR (COALESCE(A.S_UNITS, 0) + COALESCE(b.S_UNITS, 0) = 0 AND COALESCE(A.XL_UNITS, 0) + COALESCE(b.XL_UNITS, 0) = 0) OR (COALESCE(A.M_UNITS, 0) + COALESCE(b.M_UNITS, 0) = 0 AND COALESCE(A.L_UNITS, 0) + COALESCE(b.L_UNITS, 0) = 0) OR (COALESCE(A.M_UNITS, 0) + COALESCE(b.M_UNITS, 0) = 0 AND COALESCE(A.XL_UNITS, 0) + COALESCE(b.XL_UNITS, 0) = 0) OR (COALESCE(A.L_UNITS, 0) + COALESCE(b.L_UNITS, 0) = 0 AND COALESCE(A.XL_UNITS, 0) + COALESCE(b.XL_UNITS, 0) = 0) THEN \'Yes\' ELSE \'No\' END AS CUT_size_with_JIT_flag, CASE WHEN (A.S_UNITS = 0 AND A.M_UNITS = 0) OR (A.S_UNITS = 0 AND A.L_UNITS = 0) OR (A.S_UNITS = 0 AND A.XL_UNITS = 0) OR (A.M_UNITS = 0 AND A.L_UNITS = 0) OR (A.M_UNITS = 0 AND A.XL_UNITS = 0) OR (A.L_UNITS = 0 AND A.XL_UNITS = 0) THEN \'Yes\' ELSE \'No\' END AS CUT_size_flag FROM overall_jit A FULL OUTER JOIN jit B ON A.store = B.BRANCH_CODE AND A.sku_group_final = B.SKU_GROUP ) where SKU_GROUP not like \'CB%\' AND MARKETPLACE_MAPPED not like \'%WH%\' ), DETAILS AS ( select designs, collar_new, material_new, occassion_new, print_design, sleeve_type, fit, style, color, PRODUCT_TYPE as new_category, sku_group, from snitch_db.maplemonk.metafields_data order by sku_group ) Select a.*, b.designs, b.new_category, b.collar_new, b.material_new, b.occassion_new, b.print_design, b.sleeve_type, b.fit, b.style, b.color from complete a left join DETAILS b on a.SKU_GROUP =b.SKU_GROUP ) ), pareto_final as ( With over as ( With overall as ( WITH sku_group_data AS ( SELECT BRANCH_CODE, sku_group as sku_group_final, order_date, suborder_quantity -return_quantity as QTY, SELLING_PRICE - return_sales as Total_sales, FROM ( WITH ABS AS ( SELECT sku_group, BRANCH_CODE, order_date, suborder_quantity, SELLING_PRICE, FROM snitch_db.MAPLEMONK.STORE_fact_items_offline ), ACC AS ( SELECT sku_group, BRANCH_CODE, order_date, suborder_quantity AS return_quantity, SELLING_PRICE AS Return_sales FROM snitch_db.MAPLEMONK.store_returns_fact_items ) SELECT A.*, coalesce(B.return_quantity, 0) AS return_quantity, coalesce(B.Return_sales,0) as return_sales FROM ABS A FULL OUTER JOIN ACC B ON A.sku_group = B.sku_group AND A.order_date = B.order_date AND A.BRANCH_CODE = B.BRANCH_CODE ) WHERE SKU_GROUP NOT LIKE \'CB%\' ), StoreSales AS ( SELECT BRANCH_CODE, sku_group_final, SUM(TOTAL_SALES) AS TOTAL_SALES FROM sku_group_data where CURRENT_DATE - order_date <= 30 GROUP BY sku_group_final,BRANCH_CODE ), RankedSales AS ( SELECT *, 100 * DIV0(TOTAL_SALES, SUM(TOTAL_SALES) OVER (PARTITION BY BRANCH_CODE)) AS share FROM StoreSales order by share desc ), Pareot as ( Select *, SUM(share) OVER (PARTITION BY BRANCH_CODE ORDER BY share DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_share from RankedSales order by share desc ), Ratio as ( Select *, CASE WHEN cumulative_share <= 10 THEN \'10%\' WHEN cumulative_share <= 20 and cumulative_share >= 10 THEN \'20%\' WHEN cumulative_share <= 30 and cumulative_share >= 20 THEN \'30%\' WHEN cumulative_share <= 40 and cumulative_share >= 30 THEN \'40%\' WHEN cumulative_share <= 50 and cumulative_share >= 40 THEN \'50%\' WHEN cumulative_share <= 60 and cumulative_share >= 50 THEN \'60%\' WHEN cumulative_share <= 70 and cumulative_share >= 60 THEN \'70%\' WHEN cumulative_share <= 80 and cumulative_share >= 70 THEN \'80%\' WHEN cumulative_share <= 90 and cumulative_share >= 80 THEN \'90%\' ELSE \'100%\' END AS percentage_category from Pareot) Select * from Ratio ), details as ( Select * from ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY order_date DESC) AS row_number FROM snitch_db.maplemonk.STORE_fact_items_offline) where row_number =1 ) Select a.*, b.marketplace_mapped, from overall a left join details b on a.branch_code = b.branch_code ), class as ( Select sku_group, category, sku_class, product_name from snitch_db.maplemonk.availability_master_v2 ) Select a.*, b.category, b.sku_class, b.product_name from over a left join class b on a.SKU_GROUP_FINAL = b.sku_group ) Select a.*, b.CUMULATIVE_SHARE, b.PERCENTAGE_CATEGORY from master_final a left join pareto_final b on a.BRANCH_CODE =b.BRANCH_CODE and a.SKU_GROUP =b.SKU_GROUP_FINAL ) ), class as ( SELECT SKU_GROUP , SKU_CLASS, FINAL_ROS, NATURAL_ROS FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY 1) AS RN FROM SNITCH_DB.MAPLEMONK.availability_master_v2 ) where RN = 1 ) Select a.*, b.sku_class, b.final_ros as online_final_ros, b.natural_ros as online_natural_ros from offline_master a left join class b on a.sku_group = b.sku_group ) ), FILE_a AS ( sELECT * FROM SNITCH_DB.MAPLEMONK.MASTER_FILE ) Select a.*, b.CLUSTER, b.\"BOH AREA\" as BOH_AREA, b.\"BASE STOCK\" AS BASE_STOCK, b.\"CARPET AREA\" AS CARPET_AREA, b.\"VM OPTION CAPACITY\" AS VM_OPTION, b.\"DOI BOH\" AS DEPT_IDEAL From details_23 a left join FILE_a b on a.BRANCH_CODE =b.\"STORE CODE\" ) a LEFT JOIN snitch_db.maplemonk.master_offine AS B ON A.BRANCH_CODE = B.\"BRANCH CODE\" ;",
